package com.gl.hack26.crashpilot.util

import android.content.Context
import java.text.SimpleDateFormat
import java.util.Locale

/**
 * CrashSimulator provides realistic, human-like crash scenarios that commonly occur
 * in real-world Android applications. These are NOT intentionally created crashes,
 * but rather scenarios that developers might encounter due to common coding mistakes
 * or edge cases.
 */
@Suppress("UNUSED_VARIABLE", "DIVISION_BY_ZERO", "UNCHECKED_CAST")
object CrashSimulator {

    /**
     * Simulates a race condition crash - common when multiple threads access shared data
     */
    fun simulateRaceConditionCrash() {
        val sharedList = mutableListOf("Item1", "Item2", "Item3")
        Thread {
            // Simulating concurrent modifications
            for (i in 0..10) {
                if (i % 3 == 0) {
                    sharedList.add("NewItem$i")
                }
            }
        }.start()

        // Access list while another thread might be modifying it
        for (item in sharedList) {
            val processedItem = item.uppercase()
        }
    }

    /**
     * Simulates memory leak and OutOfMemoryError crash
     * This would occur when app tries to allocate huge amount of memory
     */
    fun simulateMemoryPressureCrash() {
        try {
            val hugeList = mutableListOf<ByteArray>()
            // Try to allocate large chunks (will likely fail gracefully)
            repeat(1000) {
                hugeList.add(ByteArray(1024 * 1024)) // 1 MB each
            }
        } catch (e: OutOfMemoryError) {
            throw RuntimeException("Memory allocation failed", e)
        }
    }

    /**
     * Simulates common JSON/API parsing error
     */
    fun simulateJsonParsingCrash(jsonString: String) {
        try {
            // Attempting to parse malformed JSON
            val parts = jsonString.split(",")
            val key = parts[0].split(":")[0]
            val value = parts[1].split(":")[1]
            val parsedValue = value.toInt()
        } catch (e: Exception) {
            throw RuntimeException("Failed to parse JSON response", e)
        }
    }

    /**
     * Simulates date/time formatting crash with locale issues
     */
    fun simulateDateFormatCrash(dateString: String) {
        try {
            val formatter = SimpleDateFormat("dd/MM/yyyy", Locale.US)
            val date = formatter.parse(dateString)
            // Simulating timezone conversion issue
            val milliseconds = date!!.time / 0 // ArithmeticException
        } catch (e: Exception) {
            throw RuntimeException("Date formatting error", e)
        }
    }

    /**
     * Simulates weak reference cleanup issue
     */
    fun simulateWeakReferenceCrash() {
        var tempObject: String? = "Temporary Data"
        System.gc() // Force garbage collection
        // Reference might be cleared, causing null pointer
        val length = tempObject!!.length
    }

    /**
     * Simulates Fragment lifecycle state inconsistency crash
     */
    fun simulateFragmentLifecycleCrash() {
        var isFragmentVisible = false
        var onDestroyCalled = true

        // Attempting to perform operation after fragment destroyed
        if (!onDestroyCalled) {
            throw IllegalStateException("Fragment has been destroyed")
        }
        if (isFragmentVisible) {
            // This would never execute but represents common lifecycle bug
            val data = "View Data"
        }
    }

    /**
     * Simulates resource not found crash (common with drawable/layout resources)
     */
    fun simulateResourceNotFoundCrash(context: Context, resourceId: Int) {
        try {
            val resource = context.resources.getResourceName(resourceId)
            // Attempting to load non-existent resource
            val density = context.resources.displayMetrics.density
            val dimension = context.resources.getDimensionPixelSize(9999) // Non-existent ID
        } catch (e: Exception) {
            throw RuntimeException("Resource not found: $resourceId", e)
        }
    }

    /**
     * Simulates Realm/Database corruption crash during transaction
     */
    fun simulateDatabaseTransactionCrash() {
        var transactionStarted = false
        try {
            transactionStarted = true
            // Simulating database write failure
            val writeCount = 0
            val division = 100 / writeCount // ArithmeticException during transaction
        } finally {
            // Attempting cleanup on corrupted transaction
            if (transactionStarted) {
                // Database might be in inconsistent state
            }
        }
    }

    /**
     * Simulates SharedPreferences corruption crash
     */
    fun simulatePreferencesCorruptionCrash(context: Context) {
        try {
            val prefs = context.getSharedPreferences("app_data", Context.MODE_PRIVATE)
            val serializedData = prefs.getString("complex_object", null)

            // Attempting to deserialize corrupted data
            val parts = serializedData!!.split("|")
            val userId = parts[5].toInt() // IndexOutOfBoundsException if data corrupted
        } catch (e: Exception) {
            throw RuntimeException("SharedPreferences corruption detected", e)
        }
    }

    /**
     * Simulates EditText text watcher crash from removed listener
     */
    fun simulateTextWatcherCrash() {
        // Common crash when TextWatcher is removed but still referenced
        val listeners = mutableListOf<String>("OnTextChange", "BeforeTextChange")

        for (listener in listeners) {
            if (listener == "OnTextChange") {
                listeners.remove(listener) // Unsafe iteration
            }
        }
    }

    /**
     * Simulates WorkManager/JobScheduler crash
     */
    fun simulateSchedulerCrash() {
        val jobQueue = mutableListOf<String>()
        var jobId = 0

        if (jobId < 0) {
            throw IllegalArgumentException("Job ID cannot be negative")
        }

        if (jobQueue.isEmpty()) {
            val job = jobQueue[0] // IndexOutOfBoundsException
        }
    }

    /**
     * Simulates AnimatorListener callback crash
     */
    fun simulateAnimationCrash() {
        val animationState: String? = null

        when {
            animationState == "RUNNING" -> {
                val duration = animationState.length // NullPointerException
            }
            animationState == "COMPLETED" -> {
                // Callback might fire after fragment destroyed
            }
            else -> {
                throw IllegalStateException("Unknown animation state: $animationState")
            }
        }
    }

    /**
     * Simulates retrofit/OkHttp response parsing crash
     */
    fun simulateHttpResponseCrash(responseBody: String) {
        try {
            val statusLines = responseBody.split("\n")
            val statusCode = statusLines[0].toInt()

            // Attempting to parse error response
            val errorMessage = statusLines[2] // Might not exist
            val timestamp = System.currentTimeMillis() / 0 // ArithmeticException
        } catch (e: Exception) {
            throw RuntimeException("Failed to parse HTTP response", e)
        }
    }

    /**
     * Simulates bitmap loading/scaling crash
     */
    fun simulateBitmapCrash(width: Int, height: Int) {
        try {
            // Common crash with invalid dimensions
            val area = width * height
            val byteSize = area * 4 // RGBA

            if (width == 0 || height == 0) {
                throw IllegalArgumentException("Invalid bitmap dimensions: $width x $height")
            }

            // Attempting to allocate bitmap with bad dimensions
            val scale = width / 0 // ArithmeticException
        } catch (e: Exception) {
            throw RuntimeException("Bitmap allocation failed", e)
        }
    }

    /**
     * Simulates TypeToken/Generics erasure crash
     */
    fun simulateGenericsErasureCrash() {
        val objectList: Any = listOf("item1", 2, "item3")

        // Type checking fails due to generics erasure
        @Suppress("UNCHECKED_CAST")
        val intList = (objectList as List<Int>)

        // This will fail at runtime
        val sum = intList.map { it * 2 }.sum()
    }

    /**
     * Simulates Service/foreground notification crash
     */
    fun simulateServiceNotificationCrash() {
        val channelId: String? = null
        val notificationId = -1

        if (notificationId < 0) {
            throw IllegalArgumentException("Notification ID must be positive")
        }

        // Missing notification channel on Android 8+
        val channel = channelId ?: throw RuntimeException("Notification channel not initialized")
    }
}

package com.gl.hack26.crashpilot.viewmodel

import androidx.lifecycle.LiveData
import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.ViewModel
import com.gl.hack26.crashpilot.Product
import com.gl.hack26.crashpilot.repository.ProductRepository

class ProductViewModel : ViewModel() {
    private val repository = ProductRepository()

    private val _products = MutableLiveData<List<Product>>()
    val products: LiveData<List<Product>> get() = _products

    init {
        loadProducts()
    }

    private fun loadProducts() {
        _products.value = repository.getProducts()
    }

    fun triggerRandomCrash(productId: Int, isDetailView: Boolean = false) {
        val randomValue = (0..100).random()

        // 20% chance to crash if in detail view, or 5% chance during list binding
        val crashThreshold = if (isDetailView) 20 else 5

        if (randomValue < crashThreshold) {
            when (productId % 4) {
                0 -> {
                    // Realistic ArithmeticException: Rating calculation with zero reviews
                    val totalRating = 50
                    val reviewCount = 0
                    val averageRating = totalRating / reviewCount
                }
                1 -> {
                    // Realistic IndexOutOfBoundsException: Accessing a 'featured' item from an empty promotion list
                    val promotions = listOf<String>()
                    val featuredPromo = promotions[0]
                }
                2 -> {
                    // Realistic NumberFormatException: Parsing price from a localized string without proper handling
                    val priceString = "$99.99"
                    val price = priceString.toDouble() 
                }
                3 -> {
                    // Realistic NullPointerException: Repository returns null for an invalid ID
                    val product = repository.getProductById(-1)
                    val nameLength = product!!.product_name.length
                }
            }
        }
    }

    fun triggerCrash(productId: Int, productName: String?) {
        // Keeping this for compatibility but making it random too
        triggerRandomCrash(productId, true)
    }

    fun triggerListCrash() {
        // Keeping this for compatibility but making it random too
        triggerRandomCrash(0, false)
    }
}

package com.gl.hack26.crashpilot.viewmodel

import androidx.lifecycle.LiveData
import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.ViewModel
import com.gl.hack26.crashpilot.Product
import com.gl.hack26.crashpilot.repository.ProductRepository
import java.text.SimpleDateFormat
import java.util.Locale

class ProductViewModel : ViewModel() {
    private val repository = ProductRepository()

    private val _products = MutableLiveData<List<Product>>()
    val products: LiveData<List<Product>> get() = _products

    init {
        loadProducts()
    }

    private fun loadProducts() {
        _products.value = repository.getProducts()
    }

    @Suppress("UNUSED_VARIABLE", "DIVISION_BY_ZERO", "PLATFORM_CLASS_MAPPED_TO_KOTLIN", "UNCHECKED_CAST")
    fun triggerRandomCrash(productId: Int, isDetailView: Boolean = false) {
        val randomValue = (0..100).random()

        // 20% chance to crash if in detail view, or 5% chance during list binding
        val crashThreshold = if (isDetailView) 20 else 5

        if (randomValue < crashThreshold) {
            when (productId % 24) {
                0 -> {
                    // Realistic ArithmeticException: Rating calculation with zero reviews
                    val totalRating = 50
                    val reviewCount = 0
                    val averageRating = totalRating / reviewCount
                }
                1 -> {
                    // Realistic IndexOutOfBoundsException: Accessing a 'featured' item from an empty promotion list
                    val promotions = listOf<String>()
                    val featuredPromo = promotions[0]
                }
                2 -> {
                    // Realistic NumberFormatException: Parsing price from a localized string without proper handling
                    val priceString = "$99.99"
                    val price = priceString.toDouble() 
                }
                3 -> {
                    // Realistic NullPointerException: Repository returns null for an invalid ID
                    val product = repository.getProductById(-1)
                    val nameLength = product!!.product_name.length
                }
                4 -> {
                    // Realistic ConcurrentModificationException: Modifying list while iterating
                    val cartItems = mutableListOf("Item1", "Item2", "Item3")
                    for (item in cartItems) {
                        if (item.contains("Item")) {
                            cartItems.remove(item) // Unsafe modification during iteration
                        }
                    }
                }
                5 -> {
                    // Realistic IllegalArgumentException: Invalid parameter in API call
                    val quantity = -5 // Negative quantity
                    if (quantity < 0) {
                        throw IllegalArgumentException("Quantity cannot be negative: $quantity")
                    }
                }
                6 -> {
                    // Realistic NoSuchElementException: Getting first from empty collection
                    val emptyList = emptyList<String>()
                    val firstItem = emptyList.first() // NoSuchElementException
                }
                7 -> {
                    // Realistic ClassCastException: Unsafe type casting
                    val anyValue: Any = "String Value"
                    val intValue = anyValue as Int // Direct cast without type check
                    val result = intValue * 2
                }
                8 -> {
                    // Realistic IllegalStateException: Invalid operation in wrong state
                    val isInitialized = false
                    if (!isInitialized) {
                        throw IllegalStateException("Component not initialized. Cannot perform operation.")
                    }
                }
                9 -> {
                    // Realistic StringIndexOutOfBoundsException: Accessing invalid string index
                    val productCode = "ABC"
                    val charAtIndex = productCode[productCode.length] // Invalid index
                }
                10 -> {
                    // Realistic UnsupportedOperationException: Trying unsupported collection operation
                    val readOnlyList = listOf("A", "B", "C")
                    @Suppress("UNCHECKED_CAST")
                    val mutableVersion = readOnlyList as MutableList<String>
                    mutableVersion.add("D") // Attempt to modify unmodifiable list
                }
                11 -> {
                    // Realistic ArrayIndexOutOfBoundsException: Array access out of bounds
                    val discountArray = intArrayOf(10, 20, 30)
                    val discount = discountArray[5] // Invalid index
                }
                12 -> {
                    // Realistic NullPointerException: Chained null access
                    val priceData: Map<String, String?>? = null
                    val finalPrice = priceData?.get("price")?.toInt() ?: 0
                    val adjustedPrice = finalPrice + 10
                    // Simulate accessing null pointer in chain
                    val nullValue: String? = null
                    val length = nullValue!!.length // Force NullPointerException
                }
                13 -> {
                    // Realistic AssertionError: Invalid assertion in calculation logic
                    val expected = 100
                    val actual = 50
                    assert(expected == actual) { "Calculation mismatch: expected $expected but got $actual" }
                }
                14 -> {
                    // Human-like: Date formatting crash with invalid locale data
                    val dateString = "32/13/2024" // Invalid date
                    val formatter = SimpleDateFormat("dd/MM/yyyy", Locale.US)
                    val date = formatter.parse(dateString)
                    val milliseconds = date!!.time / 0 // ArithmeticException after parsing
                }
                15 -> {
                    // Human-like: Enum constant crash
                    val statusCode = "UNKNOWN_STATUS"
                    val enumConstant = ProductStatus.valueOf(statusCode) // IllegalArgumentException
                }
                16 -> {
                    // Human-like: JSON/API parsing failure
                    val jsonResponse = "{\"price\":\"abc\",\"quantity\":2}" // Malformed
                    val priceStr = jsonResponse.split(":")[1]
                    val price = priceStr.toDouble() // NumberFormatException
                }
                17 -> {
                    // Human-like: Division by calculated value
                    val totalReviews = 10
                    val avgRating = 4.5
                    val unusedScore = totalReviews / (totalReviews - 10) // ArithmeticException
                }
                18 -> {
                    // Human-like: Last element access on possibly empty list
                    val scores = mutableListOf<Int>()
                    if (productId % 3 == 0) {
                        scores.add(100)
                    }
                    val lastScore = scores.last() // NoSuchElementException
                }
                19 -> {
                    // Human-like: Map getOrNull edge case
                    val priceMap = mapOf("item1" to 10, "item2" to 20)
                    val keys = priceMap.keys.toList()
                    val thirdKey = keys[3] // IndexOutOfBoundsException
                    val value = priceMap[thirdKey]!!.toString()
                }
                20 -> {
                    // Human-like: String split with wrong count assumption
                    val csvData = "name,price"
                    val parts = csvData.split(",")
                    val id = parts[3].toInt() // IndexOutOfBoundsException
                }
                21 -> {
                    // Human-like: Substring operation crash
                    val code = "AB"
                    val invalidSubstring = code.substring(0, 5) // StringIndexOutOfBoundsException
                }
                22 -> {
                    // Human-like: Type mismatch in collection operations
                    val mixed: List<Any> = listOf(1, "two", 3.0, "four")
                    @Suppress("UNCHECKED_CAST")
                    val numbers = mixed as List<Int>
                    val sum = numbers.map { it * 2 }.sum()
                }
                else -> {
                    // Human-like: Attempting to parse empty/corrupt response
                    val response = ""
                    val lines = response.split("\n")
                    val header = lines[0].split(":")[1] // IndexOutOfBoundsException
                    val headerHash = header.hashCode() / 0
                }
            }
        }
    }

    private enum class ProductStatus {
        AVAILABLE, OUT_OF_STOCK, DISCONTINUED
    }

    fun triggerCrash(productId: Int, productName: String?) {
        // Keeping this for compatibility but making it random too
        triggerRandomCrash(productId, true)
    }

    fun triggerListCrash() {
        // Keeping this for compatibility but making it random too
        triggerRandomCrash(0, false)
    }
}
